<?php
namespace App\Filters;
use CodeIgniter\Filters\FilterInterface;use CodeIgniter\HTTP\RequestInterface;use CodeIgniter\HTTP\ResponseInterface;
class TenantContextFilter implements FilterInterface { public function before(RequestInterface $request,$arguments=null){$u=current_user();if(!$u)return null;$workspace=$u['workspace_id']?(int)$u['workspace_id']:null;$selected=(int)session('active_workspace_id');if($selected&&(new \App\Libraries\WorkspaceAccessService())->canAccess($u,$selected))$workspace=$selected;elseif($selected)session()->remove('active_workspace_id');$reseller=$u['account_type']==='reseller'?(int)$u['id']:($u['reseller_id']?(int)$u['reseller_id']:null);service('tenantContext')->set($u,$workspace,$reseller);if($u['account_type']==='customer'&&$workspace===null){app_auth()->logout();return redirect()->to('/login')->with('error','Your account is not assigned to a workspace.');}return null;}public function after(RequestInterface $request,ResponseInterface $response,$arguments=null){} }
